comment on table SP_AREA_DETAILS_V is 'Details about Areas (used to group initiatives where are used to group projects together)';
comment on column SP_AREA_DETAILS_V.AREA_ID is 'System generated unique identifier of the area';
comment on column SP_AREA_DETAILS_V.AREA is 'Area name';
comment on column SP_AREA_DETAILS_V.DESCRIPTION is 'Area description (just the first 80 characters)';
comment on column SP_AREA_DETAILS_V.OWNER_ID is 'System generated unique identifier of the area owner (use to link to SP_PERSON_DETAILS_V)';
comment on column SP_AREA_DETAILS_V.OWNER_NAME is 'First and last name of the area owner';
comment on column SP_AREA_DETAILS_V.OWNER_EMAIL is 'Email of the area owner';
comment on column SP_AREA_DETAILS_V.TAGS is 'Comma separated list of tags associated with the area';
comment on column SP_AREA_DETAILS_V.INITIATIVE_COUNT is 'Number of initiatives associated with the area';
comment on column SP_AREA_DETAILS_V.PROJECT_COUNT is 'Number of projects associated with the area';
comment on column SP_AREA_DETAILS_V.OPEN_PROJECT_COUNT is 'Number of open projects associated with this area (not at 0 or 100 % complete)';
comment on column SP_AREA_DETAILS_V.LAST_PROJECT_CREATED_DATE is 'Most recent date on which an associated project was created';
comment on column SP_AREA_DETAILS_V.LAST_PROJECT_UPDATED_DATE is 'Most recent date on which an associated project was updated';
comment on column SP_AREA_DETAILS_V.CREATED_DATE is 'Date on which this area was created';
comment on column SP_AREA_DETAILS_V.CREATED_BY_APP_USERNAME is 'Lowercase application username of user who created the area';
comment on column SP_AREA_DETAILS_V.LAST_UPDATED_DATE is 'Date on which this area was last updated';
comment on column SP_AREA_DETAILS_V.LAST_UPDATED_BY_APP_USERNAME is 'Lowercase application username of user who last updated this area';

comment on table SP_INITIATIVE_DETAILS_V is 'Details about Initiatives (used to group projects together)';
comment on column SP_INITIATIVE_DETAILS_V.INITIATIVE_ID is 'System generated unique identifier of the initiative';
comment on column SP_INITIATIVE_DETAILS_V.INITIATIVE is 'Initiative name';
