comment on column SP_PERSON_DETAILS_V.FIRST_NAME is 'First name of the person';
comment on column SP_PERSON_DETAILS_V.LAST_NAME is 'Last name of the person';
comment on column SP_PERSON_DETAILS_V.EMAIL is 'Email address of the person';
